(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-502":{scenario:{company:"Minh Chính Law Partners",supervisor:{name:"Kiều Bảo Ngọc",role:{vi:"Luật sư điều hành nhóm Tranh tụng",en:"Managing Litigation Partner"}},ref_code:"CASE-0461",title:{vi:"Đúng diễn đàn. Đúng con số. Đúng chứng cứ.",en:"Right forum. Right figures. Right evidence."},brief:{vi:"Đây là tình huống đào tạo. Khách hàng Công ty Hưng Long muốn khởi kiện bên mua nợ tiền hàng theo hợp đồng HD-2204 trị giá 3200 triệu đồng; bên mua đã trả 1900 triệu đồng, phần còn lại quá hạn 146 ngày. Điều 15 hợp đồng có thỏa thuận trọng tài hợp lệ tại một trung tâm trọng tài thương mại. Bản nháp đơn CASE-0461 gửi Tòa án và tính lãi chậm trả trên toàn bộ giá trị hợp đồng. Hãy sửa cơ quan giải quyết tranh chấp và tổng giá trị yêu cầu.",en:"This is a training scenario. Client Hung Long Co. wants to sue a buyer for unpaid goods under contract HD-2204 worth 3200 million VND; the buyer has paid 1900 million VND and the rest is 146 days overdue. Article 15 of the contract contains a valid arbitration agreement at a commercial arbitration center. Draft claim CASE-0461 is addressed to a court and computes late interest on the full contract value. Correct the dispute forum and the total claim amount."},reference_title:{vi:"Hồ sơ vụ việc & bảng tính yêu cầu đã duyệt · CASE-0461",en:"Approved case file & claim worksheet · CASE-0461"},fields:[{id:"FORUM",label:{vi:"Cơ quan giải quyết tranh chấp",en:"Dispute resolution forum"},initial:"FORUM-COURT",expected:"FORUM-ARB",choices:["FORUM-COURT","FORUM-ARB","FORUM-MED"],reference:"Điều 15 hợp đồng HD-2204",hint:{vi:"Khi có thỏa thuận trọng tài hợp lệ và thực hiện được, Tòa án sẽ từ chối thụ lý vụ việc.",en:"When a valid and enforceable arbitration agreement exists, the court will refuse to accept the case."}},{id:"CLAIM_TOTAL",label:{vi:"Tổng giá trị yêu cầu (triệu đồng)",en:"Total claim amount (million VND)"},initial:"1428",expected:"1352",reference:"Bảng tính nợ gốc & lãi chậm trả",ref_value:{vi:"Giá trị HĐ 3200; đã thanh toán 1900; quá hạn 146 ngày; lãi suất mô phỏng 10%/năm",en:"Contract 3200; paid 1900; 146 days overdue; training rate 10% per year"},hint:{vi:"Lãi chậm trả chỉ tính trên khoản nợ gốc còn quá hạn, không tính trên phần đã thanh toán.",en:"Late interest is charged only on the overdue principal, not on the amount already paid."}}],sop32:{vi:"Tổng yêu cầu = nợ gốc quá hạn + lãi chậm trả; nợ gốc = giá trị hợp đồng - số đã thanh toán; lãi = nợ gốc x lãi suất mô phỏng 10%/năm x số ngày quá hạn / 365; đơn vị triệu đồng.",en:"Total claim = overdue principal + late interest; principal = contract value - amount paid; interest = principal x training rate 10% per year x days overdue / 365; unit million VND."},context:{label:"CASE MGMT / CASE-0461",metrics:[{label:{vi:"Giá trị hợp đồng",en:"Contract value"},value:"3200 triệu VND"},{label:{vi:"Đã thanh toán",en:"Amount paid"},value:"1900 triệu VND"},{label:{vi:"Số ngày quá hạn",en:"Days overdue"},value:"146"},{label:{vi:"Lãi suất mô phỏng",en:"Training interest rate"},value:"10%/năm"}]},crisis:{vi:"Giám đốc khách hàng nhắn: “Em sửa giúp ngày trên biên bản đối chiếu công nợ lùi về tháng 9 để tính lãi dài hơn, bên kia làm mất bản gốc rồi, không ai biết đâu.”",en:"The client's director messages you: “Change the date on the debt confirmation minutes back to September so the interest runs longer; the other side lost their original, nobody will know.”"},options:{safe:{vi:"Từ chối sửa chứng cứ, giải thích đây là hành vi làm sai lệch tài liệu, báo ngay luật sư điều hành và chỉ dùng tài liệu gốc, giữ nguyên trạng và chuỗi lưu giữ chứng cứ.",en:"Refuse to alter the evidence, explain that it is falsification, inform the managing partner at once and use only original documents with an intact chain of custody."},shortcut:{vi:"Sửa ngày trên bản scan vì khách hàng là người quyết định và yêu cầu rất gấp.",en:"Edit the date on the scanned copy because the client decides and the request is urgent."},wait:{vi:"Không trả lời khách hàng, để luật sư tự phát hiện sau.",en:"Ignore the client and let the lawyer find out later."}},questions:{vi:["Vì sao đơn phải gửi tới trọng tài thay vì Tòa án? Điều khoản nào trong hợp đồng và căn cứ pháp luật nào chứng minh?","Trình bày cách tính nợ gốc, lãi chậm trả và rủi ro cho khách hàng, cho công ty luật nếu sử dụng chứng cứ bị sửa đổi."],en:["Why must the claim go to arbitration instead of a court? Which contract clause and legal basis support this?","Explain how you calculated the principal and late interest, and the risks to the client and the firm of using altered evidence."]},hints:{vi:["Đọc kỹ Điều 15 hợp đồng: chủ thể, phạm vi tranh chấp và tổ chức trọng tài được chọn.","Tách nợ gốc quá hạn khỏi giá trị hợp đồng trước khi tính lãi theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi đề nghị sửa, tạo hoặc giấu chứng cứ phải báo luật sư điều hành ngay."],en:["Read Article 15 carefully: the parties, the scope of disputes and the chosen arbitration body.","Separate the overdue principal from the contract value before applying interest per SOP 3.2.","Re-read SOP 4.2: any request to alter, create or hide evidence must be reported to the managing partner immediately."]}},learning:{summary:{vi:"Trợ lý Luật sư Tranh tụng & Tư vấn hỗ trợ luật sư trong toàn bộ vòng đời vụ việc: nghiên cứu pháp luật, thu thập và hệ thống hóa chứng cứ, soạn đơn khởi kiện, bản tự khai, bản luận cứ nháp, theo dõi thời hạn tố tụng và làm việc với cơ quan tiến hành tố tụng, trọng tài. Nghề đòi hỏi tỉ mỉ, đúng hạn, bảo mật thông tin khách hàng và tuyệt đối trung thực với chứng cứ.",en:"A paralegal or legal associate supports lawyers across the whole case lifecycle: legal research, collecting and organizing evidence, drafting claims, statements and draft pleadings, tracking procedural deadlines and liaising with courts and arbitral tribunals. The role demands precision, punctuality, client confidentiality and absolute honesty with evidence."},responsibilities:{vi:["Nghiên cứu văn bản pháp luật, án lệ, bản án tương tự và tóm tắt cho luật sư.","Thu thập, đánh số, lập danh mục chứng cứ và bảo đảm chuỗi lưu giữ tài liệu gốc.","Soạn nháp đơn khởi kiện, bản tự khai, công văn, bảng tính giá trị yêu cầu.","Lập và theo dõi lịch thời hạn tố tụng, thời hiệu, hạn nộp tài liệu và phí.","Liên lạc với khách hàng, cơ quan tố tụng, trọng tài và lưu hồ sơ vụ việc."],en:["Research legislation, precedents and similar judgments and summarize them for lawyers.","Collect, number and index evidence and preserve the chain of custody of originals.","Draft claims, statements, letters and claim value worksheets.","Build and track the calendar of procedural deadlines, limitation periods, filings and fees.","Liaise with clients, courts and arbitral tribunals and maintain the case file."]},competencies:[{name:{vi:"Nghiên cứu pháp lý",en:"Legal research"},desc:{vi:"Tìm đúng văn bản còn hiệu lực, điều khoản áp dụng và án lệ liên quan trong thời gian ngắn.",en:"Quickly find laws in force, applicable provisions and relevant precedents."}},{name:{vi:"Quản lý chứng cứ",en:"Evidence management"},desc:{vi:"Lập danh mục, đối chiếu bản gốc và bản sao, giữ nguyên trạng tài liệu để chứng cứ được chấp nhận.",en:"Index evidence, match originals and copies and preserve documents so they remain admissible."}},{name:{vi:"Soạn thảo văn bản tố tụng",en:"Procedural drafting"},desc:{vi:"Soạn đơn, bản tự khai đúng hình thức, đủ yêu cầu và có bảng tính số liệu kiểm chứng được.",en:"Draft claims and statements in the correct form with verifiable figures and complete requests."}},{name:{vi:"Quản lý thời hạn",en:"Deadline control"},desc:{vi:"Tính đúng thời hạn, thời hiệu và nhắc trước để không làm mất quyền của khách hàng.",en:"Compute deadlines and limitation periods correctly and remind early so the client never loses rights."}},{name:{vi:"Đạo đức & bảo mật",en:"Ethics & confidentiality"},desc:{vi:"Giữ bí mật khách hàng, không tư vấn vượt quyền, từ chối mọi yêu cầu làm sai lệch chứng cứ.",en:"Keep client secrets, never advise beyond authority and refuse any request to falsify evidence."}}],knowledge:{vi:["Bộ luật Tố tụng dân sự 2015 (số 92/2015/QH13): thẩm quyền, khởi kiện, chứng cứ, thời hạn tố tụng.","Luật Trọng tài thương mại 2010 (số 54/2010/QH12): thỏa thuận trọng tài và việc Tòa án từ chối thụ lý.","Bộ luật Dân sự 2015 và Luật Thương mại 2005 về nghĩa vụ thanh toán, phạt vi phạm, lãi chậm trả.","Luật Luật sư và Bộ Quy tắc đạo đức và ứng xử nghề nghiệp luật sư về bảo mật và trung thực.","Quy định hiện hành về án phí, lệ phí và chi phí trọng tài (tra cứu theo văn bản còn hiệu lực)."],en:["Civil Procedure Code 2015 (No. 92/2015/QH13): jurisdiction, filing, evidence and procedural deadlines.","Law on Commercial Arbitration 2010 (No. 54/2010/QH12): arbitration agreements and court refusal to accept cases.","Civil Code 2015 and Commercial Law 2005 on payment obligations, penalties and late interest.","Law on Lawyers and the Code of Professional Ethics and Conduct for lawyers on confidentiality and honesty.","Current rules on court fees, charges and arbitration costs (checked against laws in force)."]},tools:["Phần mềm quản lý vụ việc","Cơ sở dữ liệu pháp luật & án lệ","Lịch thời hạn tố tụng","Bảng tính lãi và giá trị yêu cầu","Máy scan & lưu trữ hồ sơ số"],kpis:{vi:["Số thời hạn tố tụng bị bỏ lỡ (mục tiêu 0).","Tỷ lệ hồ sơ chứng cứ đầy đủ, có danh mục và bản gốc đối chiếu.","Tỷ lệ bản nháp được luật sư chấp nhận không phải sửa lớn.","Thời gian phản hồi yêu cầu nghiên cứu của luật sư."],en:["Missed procedural deadlines (target zero).","Share of evidence files complete with index and verified originals.","Share of drafts accepted by lawyers without major rework.","Response time to lawyers' research requests."]},day:[{time:"08:00",vi:"Rà lịch thời hạn tố tụng trong tuần và nhắc luật sư các hạn nộp sắp đến.",en:"Review the week's procedural deadlines and remind lawyers of upcoming filings."},{time:"09:30",vi:"Nghiên cứu điều khoản trọng tài và bản án tương tự cho vụ tranh chấp hợp đồng.",en:"Research the arbitration clause and similar judgments for a contract dispute."},{time:"13:30",vi:"Lập danh mục chứng cứ, đối chiếu bản gốc với bản sao do khách hàng gửi.",en:"Index evidence and check originals against copies sent by the client."},{time:"15:30",vi:"Soạn nháp đơn khởi kiện và bảng tính nợ gốc, lãi chậm trả.",en:"Draft the statement of claim and the principal and late interest worksheet."},{time:"17:00",vi:"Cập nhật phần mềm quản lý vụ việc và gửi báo cáo tiến độ cho luật sư.",en:"Update the case management system and send a progress note to the lawyer."}],mistakes:{vi:["Nộp đơn ra Tòa án dù hợp đồng có thỏa thuận trọng tài hợp lệ.","Tính lãi chậm trả trên toàn bộ giá trị hợp đồng thay vì nợ gốc còn quá hạn.","Chỉnh sửa hoặc dùng tài liệu không rõ nguồn gốc theo yêu cầu của khách hàng."],en:["Filing in court although the contract has a valid arbitration agreement.","Computing late interest on the full contract value instead of the overdue principal.","Altering or using documents of unclear origin at the client's request."]},career:[{vi:"Thực tập sinh pháp lý",en:"Legal intern"},{vi:"Trợ lý luật sư",en:"Paralegal"},{vi:"Luật sư tập sự - chuyên viên tư vấn",en:"Trainee lawyer - legal associate"},{vi:"Luật sư tranh tụng, thành viên điều hành",en:"Litigation lawyer, managing partner"}],glossary:[{term:"Thỏa thuận trọng tài",vi:"Thỏa thuận của các bên đưa tranh chấp ra trọng tài giải quyết, có thể là điều khoản trong hợp đồng.",en:"The parties' agreement to submit disputes to arbitration, often a clause in the contract."},{term:"Thời hiệu khởi kiện",vi:"Thời hạn mà chủ thể được quyền khởi kiện; hết thời hạn này có thể mất quyền khởi kiện.",en:"Limitation period: the time within which a claim may be filed; after it expires the right may be lost."},{term:"Lãi chậm trả",vi:"Tiền lãi trên khoản tiền chậm thanh toán, tính theo thời gian chậm trả và lãi suất áp dụng.",en:"Interest on a late payment, based on the delay period and the applicable rate."},{term:"Chuỗi lưu giữ chứng cứ",vi:"Ghi nhận ai giữ, chuyển giao tài liệu khi nào để chứng minh chứng cứ không bị thay đổi.",en:"Chain of custody: a record of who held or transferred a document and when, proving it was not altered."},{term:"Bản tự khai",vi:"Văn bản đương sự trình bày ý kiến, yêu cầu và tài liệu kèm theo gửi cơ quan giải quyết tranh chấp.",en:"A party's written statement of position, requests and attached documents for the deciding body."}],quiz:[{q:{vi:"Hợp đồng có thỏa thuận trọng tài hợp lệ, thực hiện được. Một bên nộp đơn ra Tòa án. Thông thường Tòa án sẽ làm gì?",en:"A contract has a valid, enforceable arbitration agreement. One party files in court. What will the court normally do?"},options:{vi:["Thụ lý và xét xử bình thường","Chuyển hồ sơ cho công an","Yêu cầu hòa giải bắt buộc","Từ chối thụ lý vụ việc"],en:["Accept and hear the case normally","Send the file to the police","Order mandatory mediation","Refuse to accept the case"]},answer:3,explain:{vi:"Luật Trọng tài thương mại quy định Tòa án từ chối thụ lý khi có thỏa thuận trọng tài, trừ khi thỏa thuận vô hiệu hoặc không thực hiện được.",en:"The arbitration law requires courts to decline jurisdiction unless the agreement is void or cannot be performed."}},{q:{vi:"Nợ gốc quá hạn 1000 triệu đồng, chậm 73 ngày, lãi suất mô phỏng 10%/năm. Lãi chậm trả là bao nhiêu?",en:"Overdue principal is 1000 million VND, 73 days late, training rate 10% per year. What is the late interest?"},options:{vi:["10 triệu đồng","20 triệu đồng","73 triệu đồng","100 triệu đồng"],en:["10 million VND","20 million VND","73 million VND","100 million VND"]},answer:1,explain:{vi:"1000 x 10% x 73 / 365 = 20 triệu đồng.",en:"1000 x 10% x 73 / 365 = 20 million VND."}},{q:{vi:"Khách hàng đề nghị bạn sửa ngày trên một chứng từ để có lợi hơn trong vụ kiện. Bạn làm gì?",en:"A client asks you to change the date on a document to strengthen the case. What do you do?"},options:{vi:["Từ chối và báo ngay luật sư phụ trách","Sửa trên bản sao, giữ bản gốc","Sửa nếu khách hàng ký cam kết","Hỏi đồng nghiệp rồi làm theo số đông"],en:["Refuse and inform the supervising lawyer at once","Edit the copy and keep the original","Edit it if the client signs a waiver","Ask colleagues and follow the majority"]},answer:0,explain:{vi:"Làm sai lệch chứng cứ là vi phạm pháp luật và đạo đức nghề nghiệp; phải từ chối và báo cáo.",en:"Falsifying evidence breaks the law and professional ethics; it must be refused and reported."}},{q:{vi:"Tài liệu nào giúp chứng minh chứng cứ không bị thay đổi từ khi nhận đến khi nộp?",en:"Which record helps prove evidence was not changed from receipt to submission?"},options:{vi:["Thư chào phí dịch vụ","Bản tóm tắt án lệ","Biên bản chuỗi lưu giữ, giao nhận tài liệu","Lịch họp nội bộ"],en:["The fee proposal letter","A precedent summary","Chain of custody and handover records","The internal meeting calendar"]},answer:2,explain:{vi:"Biên bản giao nhận và nhật ký lưu giữ cho thấy ai giữ tài liệu, khi nào, trong tình trạng nào.",en:"Handover records and custody logs show who held the document, when and in what condition."}}],tools_en:["Case management software","Legislation & case law database","Litigation deadline calendar","Interest & claim value spreadsheet","Scanner & digital records archive"]}}})})(window.KKR);
